param(
    [string]$CollectDir,
    [bool]$IsAdmin,
    [int]$DurationMinutes = 30,
    [int]$IntervalSeconds = 5
)

$out = Join-Path $CollectDir "01_Timeline_And_Resources"
$errors = @()

Write-Host "  Live capture running for $DurationMinutes minutes, sampling every $IntervalSeconds seconds..." -ForegroundColor Yellow
Write-Host "  Go use your laptop normally now (open Excel, browse, etc.) - that's the point." -ForegroundColor Yellow

# ---------------------------------------------------------------------------
# 1. File-open/close/size watcher for Office & common document types
# ---------------------------------------------------------------------------
$fileEventLog = New-Object System.Collections.Generic.List[Object]
$watchedExtensions = "*.xlsx","*.xls","*.docx","*.doc","*.pptx","*.ppt","*.csv","*.pdf"
$watchFolders = @(
    [Environment]::GetFolderPath("MyDocuments"),
    [Environment]::GetFolderPath("Desktop"),
    "$env:USERPROFILE\Downloads",
    "$env:USERPROFILE\OneDrive"
) | Where-Object { Test-Path $_ } | Select-Object -Unique

$watchers = @()
foreach ($folder in $watchFolders) {
    try {
        $fsw = New-Object System.IO.FileSystemWatcher
        $fsw.Path = $folder
        $fsw.IncludeSubdirectories = $true
        $fsw.Filter = "*.*"
        $fsw.NotifyFilter = [System.IO.NotifyFilters]'FileName, LastWrite, Size, CreationTime'
        $fsw.EnableRaisingEvents = $true

        $action = {
            $ext = [System.IO.Path]::GetExtension($Event.SourceEventArgs.FullPath).ToLower()
            $targetExts = @('.xlsx','.xls','.docx','.doc','.pptx','.ppt','.csv','.pdf')
            if ($targetExts -contains $ext) {
                $sizeBytes = $null
                try { if (Test-Path $Event.SourceEventArgs.FullPath) { $sizeBytes = (Get-Item $Event.SourceEventArgs.FullPath -ErrorAction SilentlyContinue).Length } } catch {}
                $global:FileEventBuffer.Add([PSCustomObject]@{
                    Timestamp   = (Get-Date).ToString("o")
                    ChangeType  = $Event.SourceEventArgs.ChangeType.ToString()
                    FullPath    = $Event.SourceEventArgs.FullPath
                    FileSizeKB  = if ($sizeBytes) { [math]::Round($sizeBytes/1KB,1) } else { $null }
                })
            }
        }
        $global:FileEventBuffer = $fileEventLog
        Register-ObjectEvent -InputObject $fsw -EventName Created -Action $action -SourceIdentifier "FSW_Created_$($folder -replace '[^a-zA-Z0-9]','')" | Out-Null
        Register-ObjectEvent -InputObject $fsw -EventName Changed -Action $action -SourceIdentifier "FSW_Changed_$($folder -replace '[^a-zA-Z0-9]','')" | Out-Null
        Register-ObjectEvent -InputObject $fsw -EventName Deleted -Action $action -SourceIdentifier "FSW_Deleted_$($folder -replace '[^a-zA-Z0-9]','')" | Out-Null
        Register-ObjectEvent -InputObject $fsw -EventName Renamed -Action $action -SourceIdentifier "FSW_Renamed_$($folder -replace '[^a-zA-Z0-9]','')" | Out-Null
        $watchers += $fsw
    } catch { $errors += "FileSystemWatcher on $folder : $($_.Exception.Message)" }
}

# ---------------------------------------------------------------------------
# 2. GPU / NPU counter discovery (best-effort - varies by driver)
# ---------------------------------------------------------------------------
$gpuCounterPaths = $null
try {
    $gpuCounterPaths = (Get-Counter -ListSet "GPU Engine" -ErrorAction Stop).PathsWithInstances |
        Where-Object { $_ -match 'engtype_3D|engtype_Compute' }
} catch { $errors += "GPU Engine counter set not available: $($_.Exception.Message)" }

$npuCounterPaths = $null
try {
    $npuSet = Get-Counter -ListSet "*NPU*" -ErrorAction SilentlyContinue
    if ($npuSet) { $npuCounterPaths = $npuSet.PathsWithInstances }
} catch { }

# Optional LibreHardwareMonitor WMI provider for temperatures if user has it running
$lhmAvailable = $false
try {
    $null = Get-CimInstance -Namespace "root/LibreHardwareMonitor" -ClassName Sensor -ErrorAction Stop
    $lhmAvailable = $true
} catch { }

# ---------------------------------------------------------------------------
# 3. Baseline process list (for start/stop diffing) and Application-log watermark
# ---------------------------------------------------------------------------
$previousProcesses = @{}
Get-Process | ForEach-Object { $previousProcesses[$_.Id] = $_.ProcessName }
$processEventLog = New-Object System.Collections.Generic.List[Object]

$captureStartTime = Get-Date
$lastAppLogCheck = $captureStartTime
$crashHangLog = New-Object System.Collections.Generic.List[Object]

# ---------------------------------------------------------------------------
# 4. Resource sample loop
# ---------------------------------------------------------------------------
$resourceSamples = New-Object System.Collections.Generic.List[Object]
$topProcessSamples = New-Object System.Collections.Generic.List[Object]
$endTime = $captureStartTime.AddMinutes($DurationMinutes)

while ((Get-Date) -lt $endTime) {
    $sampleTime = Get-Date

    # --- CPU / Memory / Disk / Network via performance counters ---
    $cpuPct = $null; $memAvailMB = $null; $diskQueueLen = $null
    try {
        $cpuPct       = (Get-Counter '\Processor(_Total)\% Processor Time' -ErrorAction Stop).CounterSamples[0].CookedValue
        $memAvailMB   = (Get-Counter '\Memory\Available MBytes' -ErrorAction Stop).CounterSamples[0].CookedValue
        $diskQueueLen = (Get-Counter '\PhysicalDisk(_Total)\Current Disk Queue Length' -ErrorAction Stop).CounterSamples[0].CookedValue
    } catch { }

    $gpuPct = $null
    if ($gpuCounterPaths) {
        try {
            $gpuSamples = Get-Counter -Counter $gpuCounterPaths -ErrorAction Stop
            $gpuPct = ($gpuSamples.CounterSamples | Measure-Object CookedValue -Sum).Sum
        } catch { }
    }

    $npuPct = $null
    if ($npuCounterPaths) {
        try {
            $npuSamples = Get-Counter -Counter $npuCounterPaths -ErrorAction Stop
            $npuPct = ($npuSamples.CounterSamples | Measure-Object CookedValue -Sum).Sum
        } catch { }
    }

    $cpuTempC = $null
    if ($lhmAvailable) {
        try {
            $tempSensor = Get-CimInstance -Namespace "root/LibreHardwareMonitor" -ClassName Sensor -ErrorAction Stop |
                Where-Object { $_.SensorType -eq 'Temperature' -and $_.Name -match 'CPU Package|Core Average' } | Select-Object -First 1
            if ($tempSensor) { $cpuTempC = $tempSensor.Value }
        } catch { }
    }

    # --- Foreground (active) window - tells you what app the user was actively using ---
    $activeWindowTitle = $null
    try {
        Add-Type -Namespace WinAPI -Name Win32 -MemberDefinition @'
[DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
[DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, System.Text.StringBuilder text, int count);
[DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint processId);
'@ -ErrorAction SilentlyContinue
        $hwnd = [WinAPI.Win32]::GetForegroundWindow()
        $sb = New-Object System.Text.StringBuilder 256
        [WinAPI.Win32]::GetWindowText($hwnd, $sb, 256) | Out-Null
        $activeWindowTitle = $sb.ToString()
    } catch { }

    $resourceSamples.Add([PSCustomObject]@{
        Timestamp          = $sampleTime.ToString("o")
        CPU_Percent        = [math]::Round($cpuPct,1)
        MemoryAvailableMB  = [math]::Round($memAvailMB,1)
        DiskQueueLength    = [math]::Round($diskQueueLen,2)
        GPU_Percent        = if ($gpuPct -ne $null) { [math]::Round($gpuPct,1) } else { "N/A" }
        NPU_Percent        = if ($npuPct -ne $null) { [math]::Round($npuPct,1) } else { "N/A" }
        CPU_Temp_C         = if ($cpuTempC -ne $null) { [math]::Round($cpuTempC,1) } else { "N/A (see 07_CPU README)" }
        ActiveWindowTitle  = $activeWindowTitle
    })

    # --- Top 5 processes by CPU/mem this sample (correlate resource spikes to specific apps) ---
    try {
        Get-Process -ErrorAction SilentlyContinue | Sort-Object WS -Descending | Select-Object -First 5 | ForEach-Object {
            $topProcessSamples.Add([PSCustomObject]@{
                Timestamp    = $sampleTime.ToString("o")
                ProcessName  = $_.ProcessName
                PID          = $_.Id
                WorkingSetMB = [math]::Round($_.WS/1MB,1)
                CPU_Seconds  = $_.CPU
            })
        }
    } catch { }

    # --- Process start/stop diffing ---
    try {
        $currentProcesses = @{}
        Get-Process | ForEach-Object { $currentProcesses[$_.Id] = $_.ProcessName }
        foreach ($pid in $currentProcesses.Keys) {
            if (-not $previousProcesses.ContainsKey($pid)) {
                $processEventLog.Add([PSCustomObject]@{ Timestamp=$sampleTime.ToString("o"); Event="Started"; ProcessName=$currentProcesses[$pid]; PID=$pid })
            }
        }
        foreach ($pid in $previousProcesses.Keys) {
            if (-not $currentProcesses.ContainsKey($pid)) {
                $processEventLog.Add([PSCustomObject]@{ Timestamp=$sampleTime.ToString("o"); Event="Stopped/Closed"; ProcessName=$previousProcesses[$pid]; PID=$pid })
            }
        }
        $previousProcesses = $currentProcesses
    } catch { }

    # --- New crash/hang events since last check (near-real-time correlation) ---
    try {
        $newEvents = Get-WinEvent -FilterHashtable @{LogName='Application'; ProviderName='Application Error','Application Hang'; StartTime=$lastAppLogCheck} -ErrorAction SilentlyContinue
        if ($newEvents) {
            foreach ($e in $newEvents) {
                $crashHangLog.Add([PSCustomObject]@{ Timestamp=$e.TimeCreated.ToString("o"); Id=$e.Id; Level=$e.LevelDisplayName; Message=($e.Message -replace "`r`n"," ") })
            }
        }
        $lastAppLogCheck = $sampleTime
    } catch { }

    Start-Sleep -Seconds $IntervalSeconds
}

# ---------------------------------------------------------------------------
# 5. Cleanup watchers, flush everything to disk
# ---------------------------------------------------------------------------
Get-EventSubscriber | Where-Object { $_.SourceIdentifier -like "FSW_*" } | Unregister-Event -ErrorAction SilentlyContinue
foreach ($w in $watchers) { $w.Dispose() }

try { $resourceSamples    | Export-Csv (Join-Path $out "ResourceUtilization_Timeline.csv") -NoTypeInformation -Encoding UTF8 } catch { $errors += "Writing resource timeline: $($_.Exception.Message)" }
try { $topProcessSamples  | Export-Csv (Join-Path $out "TopProcesses_PerSample.csv") -NoTypeInformation -Encoding UTF8 } catch { $errors += "Writing top processes: $($_.Exception.Message)" }
try { $processEventLog    | Export-Csv (Join-Path $out "ProcessStartStop_Timeline.csv") -NoTypeInformation -Encoding UTF8 } catch { $errors += "Writing process start/stop: $($_.Exception.Message)" }
try { $fileEventLog       | Export-Csv (Join-Path $out "FileOpenCloseModify_Timeline.csv") -NoTypeInformation -Encoding UTF8 } catch { $errors += "Writing file events: $($_.Exception.Message)" }
try { $crashHangLog       | Export-Csv (Join-Path $out "CrashHang_DuringCapture.csv") -NoTypeInformation -Encoding UTF8 } catch { $errors += "Writing crash/hang log: $($_.Exception.Message)" }

@"
LIVE TIMELINE CAPTURE - README
Capture window : $($captureStartTime.ToString("o")) to $((Get-Date).ToString("o"))
Sample interval: $IntervalSeconds seconds
Duration       : $DurationMinutes minutes

Files in this folder:
- ResourceUtilization_Timeline.csv : CPU%, memory available, disk queue length, GPU%, NPU%,
  CPU temp (if sensor available), and the active/foreground window title at each sample tick.
  JOIN this to the other files on the Timestamp column to correlate "what was the user doing"
  with "what did resource usage look like".
- TopProcesses_PerSample.csv : top 5 RAM-consuming processes at each sample tick - use this to
  see which specific process was responsible for a CPU/memory spike at a given timestamp.
- ProcessStartStop_Timeline.csv : every process that appeared or disappeared during the capture
  window (app launched / app closed or crashed).
- FileOpenCloseModify_Timeline.csv : file system events (Created/Changed/Deleted/Renamed) for
  Office documents, CSVs, and PDFs under Documents/Desktop/Downloads/OneDrive, with file size
  at time of event - use this to see when an Excel/Word/PPT file was created, grew, or was saved.
- CrashHang_DuringCapture.csv : any "Application Error" / "Application Hang" event that landed
  in the Application event log DURING this exact 30-minute window (real-time correlation to
  whatever spike you see in ResourceUtilization_Timeline.csv at the same timestamp).

Known limitations (be transparent with the hackathon participant about these):
- GPU_Percent / NPU_Percent will show "N/A" if the machine's driver doesn't expose that
  performance counter set - this is normal on many enterprise GPUs/iGPUs and most NPUs.
- CPU_Temp_C requires either exposed ACPI thermal WMI (rare on enterprise laptops) or
  LibreHardwareMonitor running in the background with its WMI provider enabled. If neither
  is available it will show "N/A" - see 07_CPU\TEMPERATURE_NOT_AVAILABLE_README.txt.
- File open/close is inferred from filesystem Created/Changed/Deleted events, not a true
  OS-level "handle open" event - a "Changed" event at save-time is the reliable signal;
  "opened but not saved" won't show a Changed event, only Created for new files.
"@ | Out-File (Join-Path $out "README_ThisFolder.txt") -Encoding UTF8

if ($errors.Count -eq 0) {
    [PSCustomObject]@{ Status="Success"; ItemsNote="$($resourceSamples.Count) samples, $($processEventLog.Count) proc events, $($fileEventLog.Count) file events, $($crashHangLog.Count) crash/hang events"; ErrorMessage="" }
} else {
    [PSCustomObject]@{ Status="Partial"; ItemsNote="Capture completed with some sub-collection issues"; ErrorMessage=($errors -join " | ") }
}

