cls

function Compress-Output($json) {
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)

    $outputStream = New-Object System.IO.MemoryStream
    try {
        $gzipStream = New-Object System.IO.Compression.GZipStream -ArgumentList $outputStream, ([IO.Compression.CompressionMode]::Compress)
        try {
            $gzipStream.Write($bytes, 0, $bytes.Length)
        } finally {
            $gzipStream.Dispose()
        }
        
        $compressedBytes = $outputStream.ToArray()
    } finally {
        $outputStream.Dispose()
    }

    return [Convert]::ToBase64String($compressedBytes)
}

try {
    # Get dsregcmd.exe status with error handling
    $deviceID = "Unknown"
    $domainJoined = "Unknown"

    try {
        $dsregcmdStatus = cmd /c 'C:\Windows\System32\dsregcmd.exe /status' 2>&1

        if ($?) {
            foreach ($item in $dsregcmdStatus) {
                if ($item -match "DeviceId\s+:\s+([a-fA-F0-9-]+)") {
                    $deviceID = $matches[1]
                }
                if ($item -match "DomainJoined\s+:\s+(Yes|No)") {
                    $domainJoined = $matches[1]
                }
            }
        }
    } catch {
        Write-Host "WARNING: Failed to retrieve dsregcmd.exe status"
    }

    # Get Serial Number using Get-CimInstance (better than Get-WmiObject)
    try {
        $serialNumber = (Get-CimInstance Win32_BIOS).SerialNumber
    } catch {
        $serialNumber = "Unknown"
    }

    # Get Office Update Channel safely
    $channel = "Unknown"
    $regPath = "HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration"

    if (Test-Path $regPath) {
        try {
            $channel = (Get-ItemProperty -Path $regPath).UpdateChannel
        } catch {
            $channel = "Unknown"
        }
    }

    # Get Local Admins (Ensuring at least one record is returned)
    $r = @()
    try {
        $AdminSid = New-Object System.Security.Principal.SecurityIdentifier("S-1-5-32-544")
        $group = $AdminSid.Translate([System.Security.Principal.NTAccount]).Value.Split("\")[1]

        $AdminsGroup = [ADSI]"WinNT://$env:COMPUTERNAME/$($group),group"
        $members = $AdminsGroup.psbase.Invoke("Members")

        foreach ($member in $members) {
            $memberObj = [ADSI]$member
            $r += [PSCustomObject]@{     
                Path       = $memberObj.Path.Split("/")[-1]
                Parent     = $memberObj.Parent.Split("/")[-1]
                ObjectType = $($memberObj.psbase.SchemaClassName)
            }
        }
    } catch {
        Write-Host "WARNING: Failed to retrieve local admins"
    }

    # Ensure at least one record exists
    if ($r.Count -eq 0) {
        $r += [PSCustomObject]@{
            Path       = "No local admins"
            Parent     = "N/A"
            ObjectType = "N/A"
        }
    }

    # Add additional properties
    $r | Add-Member -MemberType NoteProperty -Name device -Value $env:COMPUTERNAME -Force
    $r | Add-Member -MemberType NoteProperty -Name deviceID -Value $deviceID -Force
    $r | Add-Member -MemberType NoteProperty -Name domainJoined -Value $domainJoined -Force
    $r | Add-Member -MemberType NoteProperty -Name serialNumber -Value $serialNumber -Force
    $r | Add-Member -MemberType NoteProperty -Name updateChannel -Value $channel -Force

    # Compress output
    $compressed_results = Compress-Output -json $($r | ConvertTo-Json -Compress)

    if ($compressed_results.length -gt 2048) {
        Write-Host "ERROR: $($env:COMPUTERNAME) : Output too large, too many local admins to audit"
        exit 1
    } else {
        Write-Host $compressed_results
        exit 0
    }

} catch {
    Write-Host "ERROR: $($env:COMPUTERNAME) : $($_.Exception.Message)"
    exit 1
}


